void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}
int main(int argc,char**argv){assert(argc==2);setvbuf(stdout,nullptr,_IOLBF,0);std::array<std::string,6>paths;const char*names[]={"EGS_phantom_32.egsphant","EGS_phantom.pegs4dat","MTGP_3217_0-8191.bin","si","pgs4form.dat","tungsten-80kVp-4mmAl.spectrum"};for(int i=0;i<6;i++)paths[i]=std::string(argv[1])+"/"+names[i];egsphant_file=paths[0].c_str();pegs_file=paths[1].c_str();MT_params_file=paths[2].c_str();photon_xsections=paths[3].c_str();atomic_ff_file=paths[4].c_str();spec_file=paths[5].c_str();init(1325631759);ck(cudaDeviceSynchronize());unsigned long grand[NUM_CAT]={};unsigned long started=0,terminated=0;for(int phase=0;phase<8;phase++){simulation_step_kernel<<<dim3(1,1),32>>>(phase==0,phase!=0);ck(cudaDeviceSynchronize());sum_detector_scores_kernel<<<SUM_DETECTOR_NUM_BLOCKS,SUM_DETECTOR_WARPS_PER_BLOCK*WARP_SIZE>>>();ck(cudaDeviceSynchronize());ck(cudaMemcpy(h_total_step_counts,d_total_step_counts,sizeof(total_step_counts_t),cudaMemcpyDeviceToHost));for(int i=0;i<NUM_CAT;i++)grand[i]+=(*h_total_step_counts)[0][i];std::vector<uint4>a(32),b(32),c(32);ck(cudaMemcpy(a.data(),d_stack.a,32*sizeof(uint4),cudaMemcpyDeviceToHost));ck(cudaMemcpy(b.data(),d_stack.b,32*sizeof(uint4),cudaMemcpyDeviceToHost));ck(cudaMemcpy(c.data(),d_stack.c,32*sizeof(uint4),cudaMemcpyDeviceToHost));for(int kind=0;kind<3;kind++){std::string name="phase"+std::to_string(phase)+"_stack"+std::to_string(kind)+".bin";FILE*f=fopen(name.c_str(),"wb");assert(f);auto&v=kind==0?a:kind==1?b:c;assert(fwrite(v.data(),sizeof(uint4),v.size(),f)==v.size());fclose(f);}std::string cname="phase"+std::to_string(phase)+"_counts.bin";FILE*cf=fopen(cname.c_str(),"wb");assert(cf);assert(fwrite(h_total_step_counts,sizeof(total_step_counts_t),1,cf)==1);fclose(cf);int active=0;for(int i=0;i<32;i++){unsigned char status=*(unsigned char*)&a[i].x;assert(status<=p_empty);active+=status!=p_empty;float energy=*(float*)&a[i].y;float weight=*(float*)&a[i].z;assert(std::isfinite(energy)&&std::isfinite(weight)&&energy>=0&&weight>=0);}started=grand[p_new_particle];terminated=grand[p_cutoff_discard]+grand[p_user_discard]+grand[p_photo]+grand[p_pair];printf("READINESS_PHASE phase%d active%d started%lu terminated%lu conservation%ld photo%lu rayleigh%lu compton%lu\n",phase,active,started,terminated,long(started)-long(terminated)-active,grand[p_photo],grand[p_rayleigh],grand[p_compton]);fflush(stdout);assert(started==terminated+active);unsigned long activity=0;for(int q=0;q<8;q++)activity+=(*h_total_step_counts)[0][q];if(activity==0){assert(active==0&&phase>0);break;}assert(phase<7);}
std::vector<float>count(512*512),energy(512*512);std::vector<double>total(512*512);double countsum=0,energysum=0;for(int cat=0;cat<4;cat++){ck(cudaMemcpy(count.data(),d_detector_scores_count[0][cat],count.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(energy.data(),d_detector_scores_energy[0][cat],energy.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(total.data(),d_detector_totals_count[cat],total.size()*8,cudaMemcpyDeviceToHost));for(size_t i=0;i<count.size();i++){assert(std::isfinite(total[i])&&total[i]>=0);countsum+=total[i];}ck(cudaMemcpy(total.data(),d_detector_totals_energy[cat],total.size()*8,cudaMemcpyDeviceToHost));for(double e:total){assert(std::isfinite(e)&&e>=0);energysum+=e;}}printf("READINESS_TOTAL started%lu terminal%lu detector_weight_count%.17g detector_weight_energy%.17g\n",started,terminated,countsum,energysum);free_all();}
